"""Lightweight presentation system for customer and internal ATLAS surfaces."""
from __future__ import annotations

import html
import re

import streamlit as st


def action_class(value: object) -> str:
    token = re.sub(r"[^a-z0-9]+", "-", str(value or "RATING_NOT_PUBLISHED").lower()).strip("-")
    return f"atlas-action atlas-action-{token or 'rating-not-published'}"


def action_badge(value: object, *, label: str | None = None) -> str:
    raw = str(value or "RATING_NOT_PUBLISHED")
    text = label or raw.replace("_", " ").title()
    return f'<span class="{action_class(raw)}"><i aria-hidden="true"></i>{html.escape(text)}</span>'


